<?php
require 'db.php'; session_start(); require 'includes.php';
if (($_SESSION['user_role'] ?? '') !== 'student') { header('Location: login.php'); exit; }
$userId = (int)$_SESSION['user_id'];
$stmt = $conn->prepare('SELECT * FROM users WHERE id=?'); $stmt->bind_param('i',$userId); $stmt->execute(); $user=$stmt->get_result()->fetch_assoc(); $stmt->close();
if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (isset($_POST['update_profile'])) {
    $phone=trim($_POST['phone']??''); $father=trim($_POST['father']??''); $mother=trim($_POST['mother']??''); $branch=trim($_POST['branch']??''); $address=trim($_POST['address']??'');
    if (!$phone || !$father || !$branch || !$address) flash('error','Please complete the required profile fields.');
    else { $avatar=$user['avatar_path']; if (!empty($_FILES['avatar']['name']) && $_FILES['avatar']['error']===UPLOAD_ERR_OK) { $ext=strtolower(pathinfo($_FILES['avatar']['name'],PATHINFO_EXTENSION)); if (in_array($ext,['jpg','jpeg','png','webp'],true) && $_FILES['avatar']['size']<=2*1024*1024) { $avatar='uploads/avatar_'.$userId.'_'.time().'.'.$ext; move_uploaded_file($_FILES['avatar']['tmp_name'],__DIR__.'/'.$avatar); } else flash('error','Use a JPG, PNG or WEBP image under 2 MB.'); }
      if (!isset($_SESSION['flash'])) { $q=$conn->prepare('UPDATE users SET phone_number=?, fathers_name=?, mothers_name=?, branch=?, permanent_address=?, avatar_path=? WHERE id=?'); $q->bind_param('ssssssi',$phone,$father,$mother,$branch,$address,$avatar,$userId); $q->execute(); $q->close(); flash('success','Your profile has been updated.'); }
    }
    header('Location: student_dashboard.php#profile'); exit;
  }
  if (isset($_POST['change_password'])) { $current=$_POST['current_password']??''; $new=$_POST['new_password']??''; if (strlen($new)<8) flash('error','Your new password must have at least 8 characters.'); elseif (!password_verify($current,$user['password'])) flash('error','Your current password is incorrect.'); else { $hash=password_hash($new,PASSWORD_DEFAULT); $q=$conn->prepare('UPDATE users SET password=? WHERE id=?'); $q->bind_param('si',$hash,$userId); $q->execute(); flash('success','Password changed successfully.'); } header('Location: student_dashboard.php#profile'); exit; }
  if (isset($_POST['lock_room'])) { $roomId=(int)($_POST['room_id']??0); $roll=trim($_POST['roll_no']??''); $duration=$_POST['stay_duration']==='Month'?'Month':'Semester';
    $active=$conn->prepare("SELECT id FROM room_requests WHERE user_id=? AND status IN ('Pending','Approved')"); $active->bind_param('i',$userId); $active->execute(); $has=$active->get_result()->num_rows>0; $active->close();
    if (!$roll || !$roomId) flash('error','Choose a room and provide your roll number.'); elseif ($has) flash('error','You already have an active room request.'); else { $conn->begin_transaction(); try { $room=$conn->prepare('SELECT fees_per_sem,available_beds FROM rooms WHERE id=? FOR UPDATE'); $room->bind_param('i',$roomId); $room->execute(); $roomData=$room->get_result()->fetch_assoc(); if (!$roomData || $roomData['available_beds']<1) throw new Exception('This room has just become unavailable.'); $amount=$duration==='Month'?round($roomData['fees_per_sem']/6):$roomData['fees_per_sem']; $q=$conn->prepare("INSERT INTO room_requests (user_id,room_id,roll_no,stay_duration,status,payment_status,final_amount) VALUES (?,?,?,'$duration','Pending','Unpaid',?)"); $q->bind_param('iisd',$userId,$roomId,$roll,$amount); $q->execute(); $q=$conn->prepare('UPDATE rooms SET available_beds=available_beds-1 WHERE id=? AND available_beds>0'); $q->bind_param('i',$roomId); $q->execute(); $conn->commit(); flash('success','Room request submitted. Your bed is temporarily reserved.'); } catch (Throwable $e) { $conn->rollback(); flash('error',$e->getMessage()); } } header('Location: student_dashboard.php'); exit;
  }
}
$stats=$conn->query("SELECT COUNT(*) total, SUM(status='Pending') pending, SUM(status='Approved') approved FROM room_requests WHERE user_id=$userId")->fetch_assoc();
$history=$conn->query("SELECT req.*,r.room_number,r.room_type FROM room_requests req JOIN rooms r ON r.id=req.room_id WHERE req.user_id=$userId ORDER BY req.created_at DESC LIMIT 10");
$rooms=$conn->query('SELECT * FROM rooms ORDER BY room_number'); $flash=consume_flash(); $complete=!empty($user['phone_number'])&&!empty($user['fathers_name'])&&!empty($user['branch']);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Portal · StaySpace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/app.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script></head>
<body><div class="app"><aside class="sidebar"><div class="brand"><i class="fa-solid fa-building-shield"></i><span>StaySpace</span></div><div class="nav-label">STUDENT PORTAL</div><nav class="nav"><a class="active" href="#overview"><i class="fa-solid fa-table-columns"></i><span>Overview</span></a><a href="#rooms"><i class="fa-solid fa-bed"></i><span>Find a room</span></a><a href="#history"><i class="fa-solid fa-clock-rotate-left"></i><span>Request history</span></a><a href="#profile"><i class="fa-solid fa-user"></i><span>My profile</span></a><a class="logout" href="logout.php"><i class="fa-solid fa-arrow-right-from-bracket"></i><span>Sign out</span></a></nav></aside>
<main class="content"><header class="topbar"><div><h1>Welcome back, <?=e(explode(' ',$user['name'])[0])?></h1><p class="eyebrow">Here’s your hostel stay at a glance.</p></div><div class="top-actions"><button class="icon-btn" data-theme-toggle title="Toggle colour mode"><i class="fa-solid fa-moon"></i></button><img class="avatar" src="<?=avatar_url($user['avatar_path'],$user['name'])?>" alt="Profile photo"><span class="name"><?=e($user['name'])?></span></div></header>
<section id="overview" class="stats"><div class="stat-card"><i class="stat-icon fa-solid fa-file-lines"></i><div class="stat-label">Total requests</div><div class="stat-number"><?=$stats['total']??0?></div></div><div class="stat-card"><i class="stat-icon fa-solid fa-hourglass-half"></i><div class="stat-label">Awaiting review</div><div class="stat-number"><?=$stats['pending']??0?></div></div><div class="stat-card"><i class="stat-icon fa-solid fa-circle-check"></i><div class="stat-label">Approved stays</div><div class="stat-number"><?=$stats['approved']??0?></div></div><div class="stat-card"><i class="stat-icon fa-solid fa-bell"></i><div class="stat-label">Notifications</div><div class="stat-number"><?=($stats['pending']??0)>0?'1':'0'?></div></div></section>
<div class="grid-2"><section class="card"><div class="card-heading"><h2>Request timeline</h2></div><div class="timeline"><?php if(($stats['total']??0)==0):?><p class="muted">Choose a room below to begin your application.</p><?php else: while($item=$history->fetch_assoc()):?><div class="timeline-item"><strong><?=e($item['status'])?> · Room <?=e($item['room_number'])?></strong><br><small class="muted"><?=date('d M Y',strtotime($item['created_at']))?> · <?=e($item['stay_duration'])?> plan</small></div><?php endwhile; $history->data_seek(0); endif;?></div></section><section class="card"><div class="card-heading"><h2>Notifications</h2></div><?php if(($stats['pending']??0)>0):?><p><span class="badge pending">Pending</span> Your request is with the hostel office.</p><?php elseif(($stats['approved']??0)>0):?><p><span class="badge pending">Payment due</span> Your room is approved. The office will issue your receipt after marking payment as paid.</p><?php else:?><p class="muted">You’re all caught up. We’ll notify you here about your request.</p><?php endif;?></section></div>
<section id="rooms" class="card"><div class="card-heading"><div><h2>Find your room</h2><p class="muted">Compare available options before submitting a request.</p></div></div><div class="toolbar"><input class="field" data-room-search placeholder="Search by room, type or block"><select data-room-filter><option value="">All availability</option><option value="available">Available now</option><option value="full">Fully occupied</option></select></div><?php if(!$complete):?><div class="empty"><i class="fa-solid fa-id-card" style="font-size:28px"></i><p>Complete your profile below before you can request a room.</p><a class="btn btn-primary" href="#profile">Complete profile</a></div><?php else:?><form method="post"><div class="form-grid" style="margin-bottom:18px"><div class="form-group"><label>Roll number / registration ID</label><input required name="roll_no" placeholder="e.g. 25ESKCS101"></div><div class="form-group"><label>Stay plan</label><select name="stay_duration"><option value="Semester">Full semester</option><option value="Month">One month</option></select></div></div><div class="room-grid"><?php while($room=$rooms->fetch_assoc()):$full=$room['available_beds']<1;$search=strtolower($room['room_number'].' '.$room['room_type'].' '.$room['location']);?><article class="card room" data-room="<?=e($search)?>" data-status="<?=$full?'full':'available'?>"><img src="<?=e(room_image($room))?>" alt="Room <?=e($room['room_number'])?>"><div class="room-body"><span class="badge <?=$full?'full':'available'?>"><?=$full?'Full':$room['available_beds'].' beds left'?></span><h3 class="room-title" style="margin-top:12px">Room <?=e($room['room_number'])?></h3><p class="muted"><?=e($room['room_type'])?> · <?=e($room['location']?:'Hostel block')?></p><div class="room-meta"><strong>₹<?=number_format($room['fees_per_sem'])?></strong><span>per semester</span></div><?php if(!$full):?><label><input type="radio" required name="room_id" value="<?=$room['id']?>"> Select room</label><?php endif;?></div></article><?php endwhile;?></div><button class="btn btn-primary" name="lock_room" style="margin-top:20px"><i class="fa-solid fa-paper-plane"></i> Submit room request</button></form><?php endif;?></section>
<section id="history" class="card"><div class="card-heading"><h2>Request history</h2><span class="muted">Showing latest 10</span></div><div class="table-wrap"><table><thead><tr><th>Room</th><th>Plan</th><th>Amount</th><th>Status</th><th>Payment</th><th>Receipt</th></tr></thead><tbody><?php if($history->num_rows===0):?><tr><td colspan="6" class="empty">No room requests yet.</td></tr><?php else:while($row=$history->fetch_assoc()):?><tr><td><strong><?=e($row['room_number'])?></strong><br><small class="muted"><?=e($row['room_type'])?></small></td><td><?=e($row['stay_duration'])?></td><td>₹<?=number_format($row['final_amount'])?></td><td><span class="badge <?=status_class($row['status'])?>"><?=e($row['status'])?></span></td><td><span class="badge <?=$row['payment_status']==='Paid'?'paid':'unpaid'?>"><?=$row['payment_status']==='Paid'?'Paid':'Due'?></span></td><td><?php if($row['status']==='Approved' && $row['payment_status']==='Paid'):?><a class="btn btn-light" href="receipt.php?id=<?=$row['id']?>" target="_blank">View receipt</a><?php elseif($row['status']==='Approved'):?><span class="muted">Available after payment</span><?php else:?><span class="muted">—</span><?php endif;?></td></tr><?php endwhile;endif;?></tbody></table></div></section>
<section id="profile" class="card"><div class="card-heading"><h2>My profile</h2></div><form method="post" enctype="multipart/form-data"><div class="form-grid"><div class="form-group"><label>Profile picture</label><input type="file" name="avatar" accept="image/png,image/jpeg,image/webp"></div><div class="form-group"><label>Email address</label><input value="<?=e($user['email'])?>" disabled></div><div class="form-group"><label>Phone number *</label><input name="phone" required value="<?=e($user['phone_number'])?>"></div><div class="form-group"><label>Branch *</label><input name="branch" required value="<?=e($user['branch'])?>"></div><div class="form-group"><label>Father’s name *</label><input name="father" required value="<?=e($user['fathers_name'])?>"></div><div class="form-group"><label>Mother’s name</label><input name="mother" value="<?=e($user['mothers_name'])?>"></div><div class="form-group" style="grid-column:1/-1"><label>Permanent address *</label><textarea name="address" required rows="3"><?=e($user['permanent_address'])?></textarea></div></div><button class="btn btn-primary" name="update_profile" style="margin-top:18px">Save profile</button></form><hr style="border:0;border-top:1px solid var(--line);margin:28px 0"><h2 style="margin-bottom:15px">Change password</h2><form method="post" class="form-grid"><div class="form-group"><label>Current password</label><input type="password" name="current_password" required></div><div class="form-group"><label>New password (8+ characters)</label><input type="password" name="new_password" minlength="8" required></div><div><button class="btn btn-light" name="change_password">Update password</button></div></form></section>
</main></div><?php if($flash):?><div id="flash" data-type="<?=e($flash['type'])?>" data-message="<?=e($flash['text'])?>"></div><?php endif;?><script src="assets/js/app.js"></script><script>const f=document.getElementById('flash');if(f)Swal.fire({toast:true,position:'top-end',showConfirmButton:false,timer:3500,icon:f.dataset.type==='success'?'success':'error',title:f.dataset.message});</script></body></html>
